                    if f[i] != f[j]:
                        new_f = [f[k] ^ (i < k < j) for k in range(n)]
                        if local_induction_dimension(new_f) == dim - 1:
                            found = True
                            break
                if found:
                    break
            if not found:
                return dim
            dim += 1

