        def is_independent(g):
            for i in range(n):
                if g[i] == f[i]:
                    return False
            return True

        dim = 0
        while True:
            new_f = [f[i] ^ random.choice([0, 1]) for i in range(n)]
            if not is_independent(new_f):
                break
            dim += 1
        return dim

    def partial_commutative_matrix(f):
        n = int(math.log2(len(f)))
        M = [[0] * (n + 1) for _ in range(n + 1)]
        for i in range(2**n):
            binary_i = format(i, f'0{n}b')
            for j in range(2**n):
                binary_j = format(j, f'0{n}b')
                if all(f[i ^ j] == (f[i] & f[j]) | (f[i] & ~f[j]) | (~f[i] & f[j])) for i in range(n)):
                    M[binary_i.count('1')][binary_j.count('1')] += 1
        return M

